ECT * FROM s25 UNION ALL SELECT * FROM s26 UNION ALL SELECT * FROM s27 UNION ALL SELECT * FROM s28) SELECT count(*) AS inserted,count(*) FILTER(WHERE entity_type='generation_price_catalog') AS price_catalog,count(*) FILTER(WHERE entity_type='depreciation_original_price') AS price_partials,count(*) FILTER(WHERE entity_type='depreciation_price_review') AS held_reviews,coalesce(jsonb_agg(id),'[]'::jsonb) AS ids FROM inserted;
